  "settings.modelProvider.help.contextWindow":
    "A capacidade de contexto que o modelo processa de uma vez, em tokens. O ZCode usa isso para gerenciar o contexto.\nNão exceda o limite real do modelo.",
  "settings.modelProvider.help.maxOutputTokens":
    "O número máximo de tokens que uma única solicitação ao modelo pode gerar.\nNão exceda o limite real do modelo.",
  "settings.modelProvider.help.inputModalities":
    "Defina os tipos de conteúdo que o modelo pode receber:\n\n- **Texto**: recebe conteúdo de texto. Obrigatório.\n- **Imagens**: recebe conteúdo de imagem.\n- **Vídeo**: recebe conteúdo de vídeo.\n- **PDF**: recebe documentos PDF diretamente.",
  "settings.modelProvider.help.outputModalities":
    "O tipo de conteúdo das respostas do modelo. No momento, só texto é suportado.",
  "settings.modelProvider.help.capabilities":
    "- **Saída estruturada**: suporta restrições de JSON Schema para campos, tipos e estrutura da saída.\n- **Pesquisa web nativa**: suporta a pesquisa web integrada da API do modelo.\n- **Mensagens de sistema no meio da conversa**: suporta inserir instruções de sistema durante a conversa.\n\nNão ative recursos que o modelo não suporta.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Defina os níveis de raciocínio disponíveis no chat. **Eles devem estar ordenados do menor para o maior esforço de raciocínio**.\nNão configure níveis que o modelo não suporta.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Use uma expressão CEL para mapear o nível de raciocínio atual, `reasoningLevel`, para campos da solicitação à API do modelo. O objeto JSON retornado pela expressão é mesclado ao corpo da solicitação.",
  "settings.modelProvider.help.advanced":
    "**Esquema de ferramentas MFJS**: ativa a compatibilidade com o Moonshot Flavored JSON Schema, usado geralmente pela API do Kimi da Moonshot. Ative apenas se a API do modelo exigir esse formato.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Encontra a configuração recomendada usando o ID do modelo, a URL base e o formato da API. O ZCode atualiza as recomendações continuamente e as sincroniza com você.\nQuando você altera uma configuração manualmente, ela passa a ser gerenciada manualmente e deixa de seguir as atualizações; as demais continuam sob a configuração inteligente.",
